<?php
chdir(__DIR__.'/../public'); require '../app/bootstrap.php';
$db=new Database();$key=date('Y-m-d');
try{$db->query("INSERT INTO scheduled_job_runs(job_key,operation_key,status) VALUES('hr_expirations',?,'running')");$db->execute([$key]);}catch(Throwable $e){echo "La ejecución de hoy ya fue iniciada.\n";exit(0);}
try{$db->query("UPDATE employee_expirations SET status='expired' WHERE status='active' AND expires_on<CURDATE()");$db->execute();$db->query("SELECT ee.*,u.full_name,et.name type_name FROM employee_expirations ee JOIN users u ON u.id=ee.user_id JOIN expiration_types et ON et.id=ee.expiration_type_id WHERE ee.status='active' AND ee.expires_on<=DATE_ADD(CURDATE(),INTERVAL et.default_notice_days DAY)");$rows=$db->resultSet();$db->query("UPDATE scheduled_job_runs SET status='success',finished_at=NOW(),details_json=? WHERE job_key='hr_expirations' AND operation_key=?");$db->execute([json_encode(['alerts'=>count($rows)],JSON_UNESCAPED_UNICODE),$key]);echo count($rows)." vencimientos próximos detectados.\n";}catch(Throwable $e){$db->query("UPDATE scheduled_job_runs SET status='failed',finished_at=NOW(),details_json=? WHERE job_key='hr_expirations' AND operation_key=?");$db->execute([json_encode(['error'=>$e->getMessage()]),$key]);throw $e;}
